+    expect(html).not.toContain("Diff layout");
+  });
+
+  test("collapses long diffs behind an expand control", () => {
+    const patch = ["@@ -0,0 +1,600 @@", ...Array.from({ length: 600 }, (_, i) => `+line ${i}`)].join("\n");
